import Container from 'react-bootstrap/Container';
import Nav from 'react-bootstrap/Nav';
import Navbar from 'react-bootstrap/Navbar';
import {Link} from 'react-router-dom';


 
const navbar = () => {
  return (
    <div>
      <Navbar expand="lg" className="bg-dark" bg="dark" data-bs-theme="dark">
        <Container>
          <Navbar.Brand href='/home'>John Deo</Navbar.Brand>
          <Navbar.Toggle aria-controls="basic-navbar-nav" />
          <Navbar.Collapse id="basic-navbar-nav">
            <Nav className="ms-auto">
              <Link to="/">Home</Link>
              <Link to="/services">Services</Link>
              <Link to="/contact">Contact</Link>
              <Link to="/portfolio">Portfolio</Link>
              <Link to="/notice">Mentions Légales</Link>
            </Nav>
            <Routes>
                <Route path="/" element={<home/>}></Route>
                <Route path="/" element={<services/>}></Route>
                <Route path="/" element={<contact/>}></Route>
                <Route path="/" element={<portfolio/>}></Route>
                <Route path="/" element={<notice/>}></Route>
            </Routes>
            
          </Navbar.Collapse>
        </Container>
      </Navbar>
    </div>
  );
}


export default navbar;
